using System.Collections.Generic;

namespace EmergencyPriority
{
    // Machine-translated UI strings (Options + panels). English is the source of truth; Get() returns the
    // locale string when present, else English. Community corrections welcome.
    public static class Translations
    {
        public static string Get(string key, string locale) =>
            (Loc.TryGetValue(locale, out var lm) && lm.TryGetValue(key, out var lv)) ? lv
            : (En.TryGetValue(key, out var v) ? v : key);

        public static readonly Dictionary<string, string> En = new Dictionary<string, string>
        {
            { "opt.Enabled.L", "Enable Emergency Priority" },
            { "opt.Enabled.D", "Keeps responding fire engines, ambulances and police cars alive and moving through traffic jams. Off = vanilla behaviour." },
            { "opt.DespawnGuard.L", "Prevent stuck responders from despawning" },
            { "opt.DespawnGuard.D", "Vanilla deletes a responding vehicle once it is flagged as stuck in traffic, and the emergency waits for a re-dispatch. With the guard, the vehicle looks for a new route instead." },
            { "opt.AutoReroute.L", "Re-route around congestion" },
            { "opt.AutoReroute.D", "Vanilla plans the route once, at dispatch. With this on, a responder that sits blocked in a jam requests a fresh route that accounts for current traffic." },
            { "opt.RerouteAfterSeconds.L", "Re-route after (seconds blocked)" },
            { "opt.RerouteAfterSeconds.D", "How long a responder must be continuously stuck behind traffic before it looks for a detour." },
            { "opt.GreenLightPriority.L", "Green lights along the route" },
            { "opt.GreenLightPriority.D", "Traffic lights on a responding vehicle's route turn green as it approaches, and stay green until it has passed. This clears the queue of cars in front of it — emergency vehicles already ignore red lights themselves, it is the traffic ahead of them that waits. Uses the game's own signal priority, so normal light phases and pedestrian crossings are still respected." },
            { "opt.GreenLightDistance.L", "Green light distance (metres)" },
            { "opt.GreenLightDistance.D", "How far ahead of a responding vehicle the traffic lights react. A light needs a few seconds to change safely, so a longer distance makes it more likely to already be green on arrival. Shorter distances hold fewer junctions open at once." },
            { "opt.GhostThroughJams.L", "Drive through stopped traffic" },
            { "opt.GhostThroughJams.D", "A responder boxed in by stopped cars in its own lane drives forward through the car in front, as if the queue had pulled aside. Only applies to stopped vehicles: the car directly ahead, or stopped cross traffic in a gridlocked junction or roundabout. Never moving cross traffic, pedestrians or signals. The game has no vehicle collisions, so the brief overlap is harmless." },
            { "opt.GhostCrawlSpeed.L", "Speed through parted traffic (m/s)" },
            { "opt.GhostCrawlSpeed.D", "How fast a responder moves while passing through stopped or pulled-over traffic. 6 m/s is about 22 km/h; 3 m/s is the speed the game itself uses when it lets a vehicle drive through a blocker." },
            { "opt.TrafficPullsOver.L", "Slow traffic pulls over" },
            { "opt.TrafficPullsOver.D", "In slow-moving traffic, the car directly ahead of a responding vehicle in the same lane brakes to a stop as if it had pulled aside, and the responder passes through it — car after car, to the head of the queue. Off = the responder only passes through cars that have already stopped." },
            { "opt.GhostUsesFreeLane.L", "Use a free lane to pass the queue" },
            { "opt.GhostUsesFreeLane.D", "A responder queued behind traffic moves into an empty neighbouring lane, passes the queue there, and cuts back into its own lane just before the junction — even if that lane is for a different turn. Works on either side, for left- or right-hand traffic." },
            { "opt.LightsInTraffic.L", "Ambulances light up to get through traffic" },
            { "opt.LightsInTraffic.D", "An ambulance carrying a patient without its sirens on (the game only uses them for a critical patient) switches them on when traffic holds it up, and off again a few seconds after it is through. While lit it gets everything a responding vehicle gets: priority, green lights and the options above." },
            { "grp.Group", "Responding vehicles" },
            { "grp.GroupLights", "Traffic lights" },
            { "grp.GroupGhost", "Stopped traffic" },
            { "grp.GroupGeneral", "General" },
        };

        public static readonly Dictionary<string, Dictionary<string, string>> Loc = new Dictionary<string, Dictionary<string, string>>
        {
                ["de-DE"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Emergency Priority aktivieren", ["opt.Enabled.D"]="Hält ausrückende Feuerwehr-, Rettungs- und Polizeifahrzeuge am Leben und in Bewegung durch Staus. Aus = Vanilla-Verhalten.", ["opt.DespawnGuard.L"]="Verhindert das Verschwinden festsitzender Einsatzfahrzeuge", ["opt.DespawnGuard.D"]="Vanilla löscht ein ausrückendes Fahrzeug, sobald es als im Stau festsitzend markiert wird, und der Einsatz wartet auf eine erneute Entsendung. Mit dem Schutz sucht das Fahrzeug stattdessen eine neue Route.", ["opt.AutoReroute.L"]="Um Staus herum umleiten", ["opt.AutoReroute.D"]="Vanilla plant die Route nur einmal, bei der Entsendung. Ist dies an, fordert ein Einsatzfahrzeug, das blockiert im Stau steht, eine neue Route an, die den aktuellen Verkehr berücksichtigt.", ["opt.RerouteAfterSeconds.L"]="Umleiten nach (Sekunden blockiert)", ["opt.RerouteAfterSeconds.D"]="Wie lange ein Einsatzfahrzeug ununterbrochen hinter dem Verkehr festsitzen muss, bevor es einen Umweg sucht.", ["opt.GreenLightPriority.L"]="Grüne Welle entlang der Route", ["opt.GreenLightPriority.D"]="Ampeln auf der Route eines ausrückenden Fahrzeugs schalten bei dessen Annäherung auf Grün und bleiben grün, bis es durchgefahren ist. Das räumt die Fahrzeugschlange vor ihm frei — Einsatzfahrzeuge ignorieren rote Ampeln ohnehin selbst, es ist der Verkehr vor ihnen, der wartet. Nutzt die spieleigene Ampelpriorität, sodass normale Ampelphasen und Fußgängerüberwege weiterhin beachtet werden.", ["opt.GreenLightDistance.L"]="Reichweite der grünen Welle (Meter)", ["opt.GreenLightDistance.D"]="Wie weit vor einem ausrückenden Fahrzeug die Ampeln reagieren. Eine Ampel braucht einige Sekunden zum sicheren Umschalten, eine größere Reichweite bedeutet also eher schon Grün bei Ankunft. Kürzere Reichweiten halten weniger Kreuzungen gleichzeitig offen.", ["grp.Group"]="Einsatzfahrzeuge", ["grp.GroupLights"]="Ampeln", ["grp.GroupGeneral"]="Allgemein", ["opt.GhostThroughJams.L"]="Durch stehenden Verkehr hindurchfahren", ["opt.GhostThroughJams.D"]="Ein Einsatzfahrzeug, das in seiner Spur von stehenden Autos eingekeilt ist, fährt durch das Fahrzeug vor ihm hindurch, als hätte die Schlange Platz gemacht. Gilt nur für stehende Fahrzeuge: das Auto direkt davor oder stehenden Querverkehr an einer blockierten Kreuzung oder in einem Kreisverkehr. Nie für fließenden Querverkehr, Fußgänger oder Ampeln. Das Spiel kennt keine Fahrzeugkollisionen, die kurze Überlappung ist daher harmlos.", ["opt.GhostCrawlSpeed.L"]="Geschwindigkeit durch geteilten Verkehr (m/s)", ["opt.GhostCrawlSpeed.D"]="Wie schnell sich ein Einsatzfahrzeug bewegt, während es durch stehenden oder zur Seite gefahrenen Verkehr fährt. 6 m/s sind etwa 22 km/h; 3 m/s ist die Geschwindigkeit, die das Spiel selbst verwendet, wenn es ein Fahrzeug durch ein Hindernis fahren lässt.", ["opt.TrafficPullsOver.L"]="Langsamer Verkehr macht Platz", ["opt.TrafficPullsOver.D"]="Bei zähfließendem Verkehr bremst das Auto direkt vor einem Einsatzfahrzeug in derselben Spur bis zum Stillstand, als wäre es zur Seite gefahren, und das Einsatzfahrzeug fährt hindurch — Auto für Auto bis an die Spitze der Schlange. Aus = das Einsatzfahrzeug fährt nur durch bereits stehende Autos.", ["opt.GhostUsesFreeLane.L"]="Freie Spur zum Überholen der Schlange nutzen", ["opt.GhostUsesFreeLane.D"]="Ein Einsatzfahrzeug, das hinter einer Schlange steht, wechselt auf eine leere Nachbarspur, überholt dort die Schlange und schert kurz vor der Kreuzung wieder in seine Spur ein — auch wenn die Nachbarspur für eine andere Abbiegerichtung bestimmt ist. Funktioniert nach beiden Seiten, bei Links- wie Rechtsverkehr.", ["grp.GroupGhost"]="Stehender Verkehr", ["opt.LightsInTraffic.L"]="Rettungswagen schalten im Stau das Blaulicht ein", ["opt.LightsInTraffic.D"]="Ein Rettungswagen mit Patient an Bord, aber ohne Blaulicht (das Spiel nutzt es nur bei kritischen Patienten), schaltet es ein, wenn ihn der Verkehr aufhält, und einige Sekunden nach dem Durchkommen wieder aus. Solange es leuchtet, erhält er alles, was ein Einsatzfahrzeug erhält: Vorrang, grüne Welle und die Optionen oben.", },
                ["es-ES"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Activar Emergency Priority", ["opt.Enabled.D"]="Mantiene con vida y en movimiento a los camiones de bomberos, ambulancias y coches de policía que acuden a una emergencia a través de los atascos. Desactivado = comportamiento vanilla.", ["opt.DespawnGuard.L"]="Evitar que los vehículos de emergencia atascados desaparezcan", ["opt.DespawnGuard.D"]="El vanilla elimina un vehículo que acude a una emergencia en cuanto se marca como atascado en el tráfico, y la emergencia espera a un nuevo despacho. Con esta protección, el vehículo busca una nueva ruta en su lugar.", ["opt.AutoReroute.L"]="Desviar para evitar la congestión", ["opt.AutoReroute.D"]="El vanilla planifica la ruta una sola vez, al despachar. Con esto activado, un vehículo que queda bloqueado en un atasco solicita una ruta nueva que tiene en cuenta el tráfico actual.", ["opt.RerouteAfterSeconds.L"]="Desviar tras (segundos bloqueado)", ["opt.RerouteAfterSeconds.D"]="Cuánto tiempo debe estar un vehículo de emergencia continuamente atascado detrás del tráfico antes de buscar un desvío.", ["opt.GreenLightPriority.L"]="Semáforos en verde a lo largo de la ruta", ["opt.GreenLightPriority.D"]="Los semáforos en la ruta de un vehículo de emergencia se ponen en verde cuando este se acerca y siguen en verde hasta que ha pasado. Esto despeja la cola de coches que tiene delante: los vehículos de emergencia ya se saltan los semáforos en rojo por sí mismos, es el tráfico que va delante el que espera. Utiliza la prioridad de semáforos propia del juego, así que se respetan las fases normales y los pasos de peatones.", ["opt.GreenLightDistance.L"]="Distancia de los semáforos en verde (metros)", ["opt.GreenLightDistance.D"]="A qué distancia por delante de un vehículo de emergencia reaccionan los semáforos. Un semáforo necesita unos segundos para cambiar de forma segura, así que una distancia mayor hace más probable que ya esté en verde al llegar. Las distancias más cortas mantienen abiertos menos cruces a la vez.", ["grp.Group"]="Vehículos de emergencia", ["grp.GroupLights"]="Semáforos", ["grp.GroupGeneral"]="General", ["opt.GhostThroughJams.L"]="Atravesar el tráfico detenido", ["opt.GhostThroughJams.D"]="Un vehículo de emergencia encajonado por coches parados en su propio carril avanza atravesando el coche que tiene delante, como si la cola se hubiera apartado. Solo se aplica a vehículos parados: el coche justo delante o el tráfico cruzado detenido en un cruce o rotonda colapsados. Nunca al tráfico cruzado en movimiento, peatones ni semáforos. El juego no tiene colisiones entre vehículos, así que el breve solapamiento es inofensivo.", ["opt.GhostCrawlSpeed.L"]="Velocidad a través del tráfico apartado (m/s)", ["opt.GhostCrawlSpeed.D"]="A qué velocidad se mueve un vehículo de emergencia mientras atraviesa tráfico parado o apartado. 6 m/s son unos 22 km/h; 3 m/s es la velocidad que usa el propio juego cuando deja que un vehículo atraviese un obstáculo.", ["opt.TrafficPullsOver.L"]="El tráfico lento se aparta", ["opt.TrafficPullsOver.D"]="Con tráfico lento, el coche justo delante de un vehículo de emergencia en el mismo carril frena hasta detenerse como si se hubiera apartado, y el vehículo de emergencia lo atraviesa, coche tras coche, hasta la cabeza de la cola. Desactivado = el vehículo de emergencia solo atraviesa coches que ya están parados.", ["opt.GhostUsesFreeLane.L"]="Usar un carril libre para adelantar la cola", ["opt.GhostUsesFreeLane.D"]="Un vehículo de emergencia retenido tras una cola se cambia a un carril contiguo vacío, adelanta la cola por él y vuelve a su carril justo antes del cruce, aunque ese carril sea para otro giro. Funciona a ambos lados, con circulación por la izquierda o por la derecha.", ["grp.GroupGhost"]="Tráfico detenido", ["opt.LightsInTraffic.L"]="Las ambulancias encienden las luces para atravesar el tráfico", ["opt.LightsInTraffic.D"]="Una ambulancia que lleva un paciente sin las sirenas encendidas (el juego solo las usa con un paciente crítico) las enciende cuando el tráfico la retiene y las apaga unos segundos después de pasar. Mientras están encendidas recibe todo lo que recibe un vehículo de emergencia: prioridad, semáforos en verde y las opciones anteriores.", },
                ["fr-FR"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Activer Emergency Priority", ["opt.Enabled.D"]="Maintient en vie et en mouvement les camions de pompiers, ambulances et voitures de police en intervention à travers les embouteillages. Désactivé = comportement du jeu de base.", ["opt.DespawnGuard.L"]="Empêcher la disparition des véhicules d'intervention bloqués", ["opt.DespawnGuard.D"]="Le jeu de base supprime un véhicule en intervention dès qu'il est signalé comme bloqué dans le trafic, et l'urgence attend une nouvelle affectation. Avec la protection, le véhicule cherche plutôt un nouvel itinéraire.", ["opt.AutoReroute.L"]="Contourner les embouteillages", ["opt.AutoReroute.D"]="Le jeu de base planifie l'itinéraire une seule fois, à l'affectation. Avec cette option, un véhicule d'intervention bloqué dans un embouteillage demande un nouvel itinéraire tenant compte du trafic actuel.", ["opt.RerouteAfterSeconds.L"]="Recalculer l'itinéraire après (secondes bloqué)", ["opt.RerouteAfterSeconds.D"]="Combien de temps un véhicule d'intervention doit rester bloqué en continu derrière le trafic avant de chercher un détour.", ["opt.GreenLightPriority.L"]="Feux verts le long de l'itinéraire", ["opt.GreenLightPriority.D"]="Les feux situés sur l'itinéraire d'un véhicule d'intervention passent au vert à son approche et le restent jusqu'à ce qu'il soit passé. Cela dégage la file de voitures devant lui : les véhicules d'intervention grillent déjà les feux rouges eux-mêmes, c'est le trafic devant eux qui attend. Utilise la priorité de feux propre au jeu, donc les phases normales et les passages piétons restent respectés.", ["opt.GreenLightDistance.L"]="Portée des feux verts (mètres)", ["opt.GreenLightDistance.D"]="À quelle distance devant un véhicule d'intervention les feux réagissent. Un feu met quelques secondes à changer en toute sécurité, une portée plus grande augmente donc les chances qu'il soit déjà vert à l'arrivée. Des portées plus courtes maintiennent moins de carrefours ouverts à la fois.", ["grp.Group"]="Véhicules d'intervention", ["grp.GroupLights"]="Feux de circulation", ["grp.GroupGeneral"]="Général", ["opt.GhostThroughJams.L"]="Traverser la circulation à l'arrêt", ["opt.GhostThroughJams.D"]="Un véhicule d'intervention coincé par des voitures arrêtées dans sa voie avance à travers la voiture qui le précède, comme si la file s'était écartée. Ne s'applique qu'aux véhicules arrêtés : la voiture juste devant, ou la circulation transversale immobilisée dans un carrefour ou un rond-point bloqué. Jamais à la circulation transversale en mouvement, aux piétons ni aux feux. Le jeu ne gère pas les collisions entre véhicules, le bref chevauchement est donc sans conséquence.", ["opt.GhostCrawlSpeed.L"]="Vitesse à travers la circulation écartée (m/s)", ["opt.GhostCrawlSpeed.D"]="Vitesse d'un véhicule d'intervention lorsqu'il traverse une circulation arrêtée ou rangée sur le côté. 6 m/s font environ 22 km/h ; 3 m/s est la vitesse que le jeu utilise lui-même lorsqu'il laisse un véhicule traverser un obstacle.", ["opt.TrafficPullsOver.L"]="La circulation lente se range", ["opt.TrafficPullsOver.D"]="Dans une circulation lente, la voiture juste devant un véhicule d'intervention dans la même voie freine jusqu'à l'arrêt comme si elle s'était rangée, et le véhicule d'intervention la traverse — voiture après voiture, jusqu'à la tête de la file. Désactivé = le véhicule d'intervention ne traverse que les voitures déjà arrêtées.", ["opt.GhostUsesFreeLane.L"]="Utiliser une voie libre pour dépasser la file", ["opt.GhostUsesFreeLane.D"]="Un véhicule d'intervention bloqué derrière une file se déporte sur une voie voisine vide, y dépasse la file et se rabat dans sa voie juste avant le carrefour — même si cette voie est réservée à une autre direction. Fonctionne des deux côtés, en conduite à gauche comme à droite.", ["grp.GroupGhost"]="Circulation à l'arrêt", ["opt.LightsInTraffic.L"]="Les ambulances allument leurs gyrophares pour traverser la circulation", ["opt.LightsInTraffic.D"]="Une ambulance transportant un patient sans ses sirènes (le jeu ne les utilise que pour un patient critique) les allume lorsque la circulation la retient, et les éteint quelques secondes après être passée. Tant qu'elles sont allumées, elle bénéficie de tout ce qu'obtient un véhicule d'intervention : priorité, feux verts et les options ci-dessus.", },
                ["it-IT"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Abilita Emergency Priority", ["opt.Enabled.D"]="Mantiene attivi e in movimento tra il traffico i mezzi di soccorso in intervento: autopompe, ambulanze e volanti della polizia. Disattivato = comportamento originale.", ["opt.DespawnGuard.L"]="Impedisci la scomparsa dei soccorritori bloccati", ["opt.DespawnGuard.D"]="L'originale elimina un veicolo in intervento non appena viene contrassegnato come bloccato nel traffico, e l'emergenza attende un nuovo invio. Con la protezione, il veicolo cerca invece un nuovo percorso.", ["opt.AutoReroute.L"]="Devia intorno alla congestione", ["opt.AutoReroute.D"]="L'originale pianifica il percorso una sola volta, all'invio. Con questa opzione attiva, un soccorritore fermo bloccato in un ingorgo richiede un percorso aggiornato che tiene conto del traffico attuale.", ["opt.RerouteAfterSeconds.L"]="Devia dopo (secondi di blocco)", ["opt.RerouteAfterSeconds.D"]="Per quanto tempo un soccorritore deve restare continuativamente bloccato nel traffico prima di cercare una deviazione.", ["opt.GreenLightPriority.L"]="Semafori verdi lungo il percorso", ["opt.GreenLightPriority.D"]="I semafori sul percorso di un mezzo di soccorso passano al verde al suo avvicinarsi e restano verdi finché non è passato. Questo libera la coda di auto davanti a lui: i mezzi di soccorso passano già con il rosso da soli, è il traffico che li precede ad aspettare. Usa la priorità semaforica propria del gioco, quindi le fasi normali e gli attraversamenti pedonali restano rispettati.", ["opt.GreenLightDistance.L"]="Distanza dei semafori verdi (metri)", ["opt.GreenLightDistance.D"]="A che distanza davanti a un mezzo di soccorso reagiscono i semafori. Un semaforo impiega qualche secondo per cambiare in sicurezza, quindi una distanza maggiore rende più probabile che sia già verde all'arrivo. Distanze più brevi tengono aperti meno incroci per volta.", ["grp.Group"]="Veicoli in intervento", ["grp.GroupLights"]="Semafori", ["grp.GroupGeneral"]="Generale", ["opt.GhostThroughJams.L"]="Attraversare il traffico fermo", ["opt.GhostThroughJams.D"]="Un mezzo di soccorso bloccato da auto ferme nella propria corsia avanza attraverso l'auto che lo precede, come se la coda si fosse scostata. Vale solo per veicoli fermi: l'auto subito davanti, o il traffico trasversale fermo in un incrocio o in una rotatoria bloccati. Mai per il traffico trasversale in movimento, i pedoni o i semafori. Il gioco non ha collisioni tra veicoli, quindi la breve sovrapposizione è innocua.", ["opt.GhostCrawlSpeed.L"]="Velocità attraverso il traffico scostato (m/s)", ["opt.GhostCrawlSpeed.D"]="Quanto velocemente si muove un mezzo di soccorso mentre attraversa traffico fermo o accostato. 6 m/s sono circa 22 km/h; 3 m/s è la velocità che il gioco stesso usa quando lascia che un veicolo attraversi un ostacolo.", ["opt.TrafficPullsOver.L"]="Il traffico lento si accosta", ["opt.TrafficPullsOver.D"]="Nel traffico lento, l'auto subito davanti a un mezzo di soccorso nella stessa corsia frena fino a fermarsi come se si fosse accostata, e il mezzo di soccorso la attraversa — auto dopo auto, fino alla testa della coda. Disattivato = il mezzo di soccorso attraversa solo le auto già ferme.", ["opt.GhostUsesFreeLane.L"]="Usa una corsia libera per superare la coda", ["opt.GhostUsesFreeLane.D"]="Un mezzo di soccorso fermo dietro una coda si sposta in una corsia adiacente vuota, supera la coda e rientra nella propria corsia subito prima dell'incrocio — anche se quella corsia è destinata a un'altra svolta. Funziona su entrambi i lati, con guida a sinistra o a destra.", ["grp.GroupGhost"]="Traffico fermo", ["opt.LightsInTraffic.L"]="Le ambulanze accendono i lampeggianti per attraversare il traffico", ["opt.LightsInTraffic.D"]="Un'ambulanza con un paziente a bordo ma senza sirene (il gioco le usa solo per un paziente critico) le accende quando il traffico la trattiene e le spegne qualche secondo dopo essere passata. Finché sono accese riceve tutto ciò che riceve un mezzo di soccorso: precedenza, semafori verdi e le opzioni sopra.", },
                ["ja-JP"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Emergency Priority を有効化", ["opt.Enabled.D"]="出動中の消防車、救急車、パトカーを渋滞の中でも消滅させず走行させ続けます。オフ = バニラの挙動。", ["opt.DespawnGuard.L"]="立ち往生した緊急車両の消滅を防止", ["opt.DespawnGuard.D"]="バニラでは、渋滞で立ち往生と判定された出動車両を削除し、緊急対応は再出動を待ちます。ガードを有効にすると、その車両は代わりに新しい経路を探します。", ["opt.AutoReroute.L"]="渋滞を迂回して再経路探索", ["opt.AutoReroute.D"]="バニラでは経路は出動時に一度だけ計画されます。これをオンにすると、渋滞で立ち往生した緊急車両が現在の交通状況を反映した新しい経路を要求します。", ["opt.RerouteAfterSeconds.L"]="再経路探索までの時間（立ち往生秒数）", ["opt.RerouteAfterSeconds.D"]="緊急車両が迂回路を探し始めるまでに、渋滞の後ろで連続して立ち往生している必要がある時間。", ["opt.GreenLightPriority.L"]="ルート上の信号を青に", ["opt.GreenLightPriority.D"]="出動中の車両のルート上にある信号機が、接近に合わせて青に変わり、通過し終えるまで青のままになります。これは前方の車列を捌くための機能です。緊急車両自体はもともと赤信号を無視して走行しており、待っているのはその前の一般車両です。ゲーム本来の信号優先制御を使うため、通常の信号サイクルや横断歩道はそのまま尊重されます。", ["opt.GreenLightDistance.L"]="信号が反応する距離（メートル）", ["opt.GreenLightDistance.D"]="出動車両のどれだけ手前から信号機が反応するか。信号が安全に切り替わるには数秒かかるため、距離が長いほど到着時点で既に青になっている可能性が高くなります。距離が短いほど、同時に開放される交差点は少なくなります。", ["grp.Group"]="出動車両", ["grp.GroupLights"]="信号機", ["grp.GroupGeneral"]="全般", ["opt.GhostThroughJams.L"]="停止した車列をすり抜ける", ["opt.GhostThroughJams.D"]="自分の車線で停止した車に囲まれた緊急車両は、列が道を空けたかのように前方の車を通り抜けて進みます。対象は停止している車両のみです：直前の車、または渋滞で動けない交差点やラウンドアバウト内の停止した交差車両。動いている交差車両、歩行者、信号には適用されません。このゲームには車両同士の衝突判定がないため、一瞬の重なりは無害です。", ["opt.GhostCrawlSpeed.L"]="道を空けた車列を通過する速度（m/s）", ["opt.GhostCrawlSpeed.D"]="停止した車両や脇に寄せた車両を通り抜ける際の緊急車両の速度。6 m/s は約 22 km/h、3 m/s はゲーム自体が車両に障害物の通り抜けを許可する際の速度です。", ["opt.TrafficPullsOver.L"]="低速の車両が道を空ける", ["opt.TrafficPullsOver.D"]="低速走行時、同じ車線で緊急車両の直前にいる車は脇に寄せたかのように減速して停止し、緊急車両はそれを通り抜けます。車を一台ずつ抜いて列の先頭まで進みます。オフ = 緊急車両はすでに停止している車のみを通り抜けます。", ["opt.GhostUsesFreeLane.L"]="空いている車線で列を追い越す", ["opt.GhostUsesFreeLane.D"]="車列の後ろで待つ緊急車両は、空いている隣の車線に移って列を追い越し、交差点の直前で元の車線に戻ります。その車線が別方向専用でも構いません。左右どちら側でも、左側通行・右側通行を問わず機能します。", ["grp.GroupGhost"]="停止した車列", ["opt.LightsInTraffic.L"]="救急車が渋滞を抜けるために警光灯を点灯", ["opt.LightsInTraffic.D"]="サイレンを鳴らさずに患者を搬送中の救急車（ゲームは重篤な患者の場合のみサイレンを使用）は、交通に足止めされると警光灯を点灯し、通過して数秒後に消灯します。点灯中は出動中の車両と同じ扱いを受けます：優先通行、青信号、そして上記のオプションです。", },
                ["ko-KR"] = new Dictionary<string, string> { ["opt.Enabled.L"]="긴급 우선 통행 활성화", ["opt.Enabled.D"]="출동 중인 소방차, 구급차, 경찰차가 교통 정체를 뚫고 계속 이동하도록 유지합니다. 꺼짐 = 기본 게임 동작.", ["opt.DespawnGuard.L"]="정체된 출동 차량의 소멸 방지", ["opt.DespawnGuard.D"]="기본 게임은 출동 차량이 교통 정체에 갇힌 것으로 표시되면 이를 삭제하고, 긴급 상황은 재출동을 기다립니다. 이 보호 기능을 켜면 차량이 대신 새 경로를 찾습니다.", ["opt.AutoReroute.L"]="정체 우회 경로 재탐색", ["opt.AutoReroute.D"]="기본 게임은 출동 시 경로를 한 번만 계획합니다. 이 옵션을 켜면 정체에 막혀 멈춰 있는 출동 차량이 현재 교통 상황을 반영한 새 경로를 요청합니다.", ["opt.RerouteAfterSeconds.L"]="재탐색 시점 (막힌 지 초)", ["opt.RerouteAfterSeconds.D"]="출동 차량이 우회로를 찾기 전에 교통에 막혀 연속으로 정체되어야 하는 시간입니다.", ["opt.GreenLightPriority.L"]="경로상의 신호등을 녹색으로", ["opt.GreenLightPriority.D"]="출동 차량의 경로에 있는 신호등이 차량이 접근하면 녹색으로 바뀌고, 통과할 때까지 녹색을 유지합니다. 이는 앞에 늘어선 차량 행렬을 정리하기 위한 기능입니다. 긴급 차량 자체는 원래 적신호를 무시하고 주행하며, 기다리는 것은 그 앞의 일반 차량입니다. 게임 자체의 신호 우선 기능을 사용하므로 일반 신호 주기와 횡단보도는 그대로 존중됩니다.", ["opt.GreenLightDistance.L"]="신호등 반응 거리 (미터)", ["opt.GreenLightDistance.D"]="출동 차량으로부터 얼마나 앞의 신호등이 반응하는지 정합니다. 신호가 안전하게 바뀌려면 몇 초가 걸리므로, 거리가 길수록 도착 시점에 이미 녹색일 가능성이 높습니다. 거리가 짧을수록 동시에 열리는 교차로가 줄어듭니다.", ["grp.Group"]="출동 차량", ["grp.GroupLights"]="신호등", ["grp.GroupGeneral"]="일반", ["opt.GhostThroughJams.L"]="정지한 차량 통과", ["opt.GhostThroughJams.D"]="자기 차선에서 정지한 차들에 갇힌 출동 차량은 차량 행렬이 비켜준 것처럼 앞차를 통과해 전진합니다. 정지한 차량에만 적용됩니다: 바로 앞의 차, 또는 꽉 막힌 교차로나 회전교차로에서 멈춰 있는 교차 차량. 움직이는 교차 차량, 보행자, 신호등에는 절대 적용되지 않습니다. 게임에는 차량 충돌이 없으므로 잠깐의 겹침은 무해합니다.", ["opt.GhostCrawlSpeed.L"]="비켜준 차량 통과 속도 (m/s)", ["opt.GhostCrawlSpeed.D"]="정지했거나 비켜선 차량을 통과할 때 출동 차량이 움직이는 속도입니다. 6 m/s는 약 22 km/h이며, 3 m/s는 게임 자체가 차량이 장애물을 통과하도록 허용할 때 사용하는 속도입니다.", ["opt.TrafficPullsOver.L"]="느린 차량이 비켜섬", ["opt.TrafficPullsOver.D"]="서행 중인 교통에서 같은 차선의 출동 차량 바로 앞 차가 비켜선 것처럼 감속해 정지하고, 출동 차량이 그 차를 통과합니다. 한 대씩 통과하며 행렬 맨 앞까지 나아갑니다. 꺼짐 = 출동 차량은 이미 정지한 차만 통과합니다.", ["opt.GhostUsesFreeLane.L"]="빈 차선으로 행렬 추월", ["opt.GhostUsesFreeLane.D"]="행렬 뒤에 막힌 출동 차량이 비어 있는 옆 차선으로 옮겨 행렬을 추월한 뒤, 교차로 직전에 원래 차선으로 되돌아옵니다. 그 차선이 다른 방향 전용이어도 상관없습니다. 양쪽 어느 방향으로든, 좌측통행과 우측통행 모두에서 작동합니다.", ["grp.GroupGhost"]="정지한 교통", ["opt.LightsInTraffic.L"]="구급차가 정체를 통과하기 위해 경광등 점등", ["opt.LightsInTraffic.D"]="사이렌 없이 환자를 이송 중인 구급차(게임은 위급 환자일 때만 사이렌을 사용)가 교통에 막히면 경광등을 켜고, 통과한 뒤 몇 초 후에 다시 끕니다. 켜져 있는 동안에는 출동 차량과 동일한 대우를 받습니다: 우선 통행, 녹색 신호, 그리고 위의 옵션들.", },
                ["pl-PL"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Włącz Emergency Priority", ["opt.Enabled.D"]="Utrzymuje interweniujące wozy strażackie, karetki i radiowozy przy życiu i w ruchu przez korki. Wyłączone = zachowanie z gry podstawowej.", ["opt.DespawnGuard.L"]="Zapobiegaj znikaniu utkniętych pojazdów ratowniczych", ["opt.DespawnGuard.D"]="Gra podstawowa usuwa interweniujący pojazd, gdy zostaje oznaczony jako utknięty w korku, a wezwanie czeka na ponowne wysłanie. Z tą ochroną pojazd zamiast tego szuka nowej trasy.", ["opt.AutoReroute.L"]="Zmiana trasy w celu ominięcia zatorów", ["opt.AutoReroute.D"]="Gra podstawowa planuje trasę tylko raz, przy wysłaniu. Gdy ta opcja jest włączona, pojazd ratowniczy stojący zablokowany w korku żąda nowej trasy uwzględniającej bieżący ruch.", ["opt.RerouteAfterSeconds.L"]="Zmiana trasy po (sekundach blokady)", ["opt.RerouteAfterSeconds.D"]="Jak długo pojazd ratowniczy musi być nieprzerwanie zablokowany w ruchu, zanim zacznie szukać objazdu.", ["opt.GreenLightPriority.L"]="Zielone światło na trasie", ["opt.GreenLightPriority.D"]="Sygnalizacja na trasie interweniującego pojazdu zmienia się na zieloną, gdy ten się zbliża, i pozostaje zielona, dopóki pojazd nie przejedzie. Udrażnia to kolejkę samochodów przed nim — pojazdy ratownicze i tak same ignorują czerwone światło, to ruch przed nimi czeka. Wykorzystuje własny mechanizm priorytetu sygnalizacji z gry, więc normalne fazy świateł i przejścia dla pieszych pozostają zachowane.", ["opt.GreenLightDistance.L"]="Zasięg zielonego światła (metry)", ["opt.GreenLightDistance.D"]="Jak daleko przed interweniującym pojazdem reaguje sygnalizacja. Bezpieczna zmiana świateł trwa kilka sekund, więc większy zasięg zwiększa szansę, że światło będzie już zielone w chwili dojazdu. Mniejszy zasięg utrzymuje otwartych mniej skrzyżowań naraz.", ["grp.Group"]="Pojazdy interweniujące", ["grp.GroupLights"]="Sygnalizacja świetlna", ["grp.GroupGeneral"]="Ogólne", ["opt.GhostThroughJams.L"]="Przejeżdżanie przez stojące pojazdy", ["opt.GhostThroughJams.D"]="Pojazd ratowniczy zablokowany przez stojące samochody na swoim pasie przejeżdża przez pojazd przed sobą, jakby kolejka się rozstąpiła. Dotyczy tylko stojących pojazdów: samochodu bezpośrednio z przodu lub zatrzymanego ruchu poprzecznego na zakorkowanym skrzyżowaniu albo rondzie. Nigdy poruszającego się ruchu poprzecznego, pieszych ani sygnalizacji. W grze nie ma kolizji pojazdów, więc chwilowe nakładanie się jest nieszkodliwe.", ["opt.GhostCrawlSpeed.L"]="Prędkość przejazdu przez rozstąpiony ruch (m/s)", ["opt.GhostCrawlSpeed.D"]="Jak szybko porusza się pojazd ratowniczy, przejeżdżając przez stojące lub zjeżdżające na bok pojazdy. 6 m/s to około 22 km/h; 3 m/s to prędkość, której sama gra używa, gdy pozwala pojazdowi przejechać przez przeszkodę.", ["opt.TrafficPullsOver.L"]="Wolny ruch zjeżdża na bok", ["opt.TrafficPullsOver.D"]="W wolnym ruchu samochód bezpośrednio przed pojazdem ratowniczym na tym samym pasie hamuje do zatrzymania, jakby zjechał na bok, a pojazd ratowniczy przejeżdża przez niego — samochód po samochodzie, aż na czoło kolejki. Wyłączone = pojazd ratowniczy przejeżdża tylko przez już stojące samochody.", ["opt.GhostUsesFreeLane.L"]="Użyj wolnego pasa, aby wyprzedzić kolejkę", ["opt.GhostUsesFreeLane.D"]="Pojazd ratowniczy stojący za kolejką zjeżdża na pusty sąsiedni pas, wyprzedza nim kolejkę i wraca na swój pas tuż przed skrzyżowaniem — nawet jeśli ten pas jest przeznaczony do innego skrętu. Działa po obu stronach, przy ruchu lewo- i prawostronnym.", ["grp.GroupGhost"]="Stojący ruch", ["opt.LightsInTraffic.L"]="Karetki włączają sygnały, aby przejechać przez korek", ["opt.LightsInTraffic.D"]="Karetka wioząca pacjenta bez włączonych sygnałów (gra używa ich tylko przy pacjencie w stanie krytycznym) włącza je, gdy zatrzymuje ją ruch, i wyłącza kilka sekund po przejechaniu. Dopóki są włączone, otrzymuje wszystko, co pojazd ratowniczy: pierwszeństwo, zielone światła i powyższe opcje.", },
                ["pt-BR"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Ativar Emergency Priority", ["opt.Enabled.D"]="Mantém caminhões de bombeiros, ambulâncias e viaturas policiais em atendimento vivos e em movimento no meio dos congestionamentos. Desativado = comportamento original.", ["opt.DespawnGuard.L"]="Impedir que veículos presos desapareçam", ["opt.DespawnGuard.D"]="O jogo original exclui um veículo em atendimento assim que ele é marcado como preso no trânsito, e a emergência aguarda um novo despacho. Com a proteção, o veículo procura uma nova rota em vez disso.", ["opt.AutoReroute.L"]="Recalcular rota contornando o congestionamento", ["opt.AutoReroute.D"]="O jogo original planeja a rota uma única vez, no despacho. Com isto ativado, um veículo que fica bloqueado em um congestionamento solicita uma rota nova que leva em conta o trânsito atual.", ["opt.RerouteAfterSeconds.L"]="Recalcular rota após (segundos bloqueado)", ["opt.RerouteAfterSeconds.D"]="Por quanto tempo um veículo precisa ficar continuamente preso atrás do trânsito antes de procurar um desvio.", ["opt.GreenLightPriority.L"]="Semáforos verdes ao longo da rota", ["opt.GreenLightPriority.D"]="Os semáforos na rota de um veículo em atendimento ficam verdes quando ele se aproxima e permanecem verdes até que ele passe. Isso libera a fila de carros à frente dele: veículos de emergência já avançam o sinal vermelho por conta própria, quem espera é o trânsito à frente deles. Usa a prioridade de semáforos do próprio jogo, então as fases normais e as faixas de pedestres continuam respeitadas.", ["opt.GreenLightDistance.L"]="Distância dos semáforos verdes (metros)", ["opt.GreenLightDistance.D"]="A que distância à frente de um veículo em atendimento os semáforos reagem. Um semáforo leva alguns segundos para mudar com segurança, então uma distância maior aumenta a chance de ele já estar verde na chegada. Distâncias menores mantêm menos cruzamentos abertos ao mesmo tempo.", ["grp.Group"]="Veículos em atendimento", ["grp.GroupLights"]="Semáforos", ["grp.GroupGeneral"]="Geral", ["opt.GhostThroughJams.L"]="Atravessar o trânsito parado", ["opt.GhostThroughJams.D"]="Um veículo de emergência encurralado por carros parados na própria faixa avança atravessando o carro à frente, como se a fila tivesse aberto passagem. Vale apenas para veículos parados: o carro logo à frente, ou o tráfego transversal parado em um cruzamento ou rotatória engarrafados. Nunca para tráfego transversal em movimento, pedestres ou semáforos. O jogo não tem colisões entre veículos, então a breve sobreposição é inofensiva.", ["opt.GhostCrawlSpeed.L"]="Velocidade através do trânsito aberto (m/s)", ["opt.GhostCrawlSpeed.D"]="Com que velocidade um veículo de emergência se move ao atravessar trânsito parado ou encostado. 6 m/s são cerca de 22 km/h; 3 m/s é a velocidade que o próprio jogo usa quando deixa um veículo atravessar um obstáculo.", ["opt.TrafficPullsOver.L"]="Trânsito lento encosta", ["opt.TrafficPullsOver.D"]="No trânsito lento, o carro logo à frente de um veículo de emergência na mesma faixa freia até parar como se tivesse encostado, e o veículo de emergência o atravessa — carro após carro, até a frente da fila. Desligado = o veículo de emergência só atravessa carros que já estão parados.", ["opt.GhostUsesFreeLane.L"]="Usar uma faixa livre para ultrapassar a fila", ["opt.GhostUsesFreeLane.D"]="Um veículo de emergência preso atrás de uma fila muda para uma faixa vizinha vazia, ultrapassa a fila por ela e volta para a própria faixa logo antes do cruzamento — mesmo que essa faixa seja para outra conversão. Funciona dos dois lados, com mão inglesa ou direita.", ["grp.GroupGhost"]="Trânsito parado", ["opt.LightsInTraffic.L"]="Ambulâncias ligam as luzes para atravessar o trânsito", ["opt.LightsInTraffic.D"]="Uma ambulância transportando um paciente sem as sirenes ligadas (o jogo só as usa com um paciente em estado crítico) as liga quando o trânsito a segura e as desliga alguns segundos depois de passar. Enquanto estiverem ligadas, ela recebe tudo o que um veículo de emergência recebe: prioridade, sinais verdes e as opções acima.", },
                ["ru-RU"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Включить Emergency Priority", ["opt.Enabled.D"]="Помогает выезжающим пожарным машинам, каретам скорой помощи и полицейским машинам не застревать и двигаться сквозь пробки. Выкл = поведение оригинала.", ["opt.DespawnGuard.L"]="Не давать застрявшим экстренным машинам исчезать", ["opt.DespawnGuard.D"]="Оригинал удаляет выехавшую машину, как только она помечена застрявшей в пробке, и экстренная служба ждёт повторной отправки. С этой защитой машина вместо этого ищет новый маршрут.", ["opt.AutoReroute.L"]="Объезд заторов", ["opt.AutoReroute.D"]="Оригинал прокладывает маршрут один раз, при отправке. С включённым параметром машина, застрявшая в пробке, запрашивает новый маршрут с учётом текущего трафика.", ["opt.RerouteAfterSeconds.L"]="Перепрокладка через (секунд в заторе)", ["opt.RerouteAfterSeconds.D"]="Сколько времени машина должна непрерывно стоять в пробке, прежде чем начнёт искать объезд.", ["opt.GreenLightPriority.L"]="Зелёный свет по маршруту", ["opt.GreenLightPriority.D"]="Светофоры на маршруте выехавшей машины переключаются на зелёный при её приближении и остаются зелёными, пока она не проедет. Это разгружает очередь машин перед ней: сами экстренные машины и так проезжают на красный, ждёт именно транспорт впереди них. Используется собственный механизм приоритета светофоров игры, поэтому обычные фазы и пешеходные переходы по-прежнему соблюдаются.", ["opt.GreenLightDistance.L"]="Дальность действия зелёного света (метры)", ["opt.GreenLightDistance.D"]="На каком расстоянии перед выехавшей машиной реагируют светофоры. Безопасное переключение занимает несколько секунд, поэтому большая дальность повышает шанс, что к моменту прибытия уже горит зелёный. Меньшая дальность удерживает открытыми меньше перекрёстков одновременно.", ["grp.Group"]="Выезжающие машины", ["grp.GroupLights"]="Светофоры", ["grp.GroupGeneral"]="Общие", ["opt.GhostThroughJams.L"]="Проезд сквозь стоящий транспорт", ["opt.GhostThroughJams.D"]="Спецмашина, зажатая стоящими автомобилями в своей полосе, проезжает сквозь машину впереди, как будто очередь расступилась. Действует только для стоящих машин: автомобиля непосредственно впереди или остановившегося поперечного потока на заблокированном перекрёстке или кольце. Никогда — для движущегося поперечного потока, пешеходов или светофоров. В игре нет столкновений между машинами, поэтому кратковременное наложение безвредно.", ["opt.GhostCrawlSpeed.L"]="Скорость проезда сквозь расступившийся поток (м/с)", ["opt.GhostCrawlSpeed.D"]="С какой скоростью спецмашина движется, проезжая сквозь стоящий или прижавшийся к обочине транспорт. 6 м/с — это около 22 км/ч; 3 м/с — скорость, которую сама игра использует, когда позволяет машине проехать сквозь препятствие.", ["opt.TrafficPullsOver.L"]="Медленный поток уступает дорогу", ["opt.TrafficPullsOver.D"]="В медленном потоке автомобиль непосредственно перед спецмашиной в той же полосе тормозит до остановки, как будто прижался к обочине, и спецмашина проезжает сквозь него — машину за машиной, до головы очереди. Выкл. = спецмашина проезжает только сквозь уже стоящие автомобили.", ["opt.GhostUsesFreeLane.L"]="Объезжать очередь по свободной полосе", ["opt.GhostUsesFreeLane.D"]="Спецмашина, стоящая за очередью, перестраивается в пустую соседнюю полосу, объезжает по ней очередь и возвращается в свою полосу перед самым перекрёстком — даже если эта полоса предназначена для другого поворота. Работает в обе стороны, при лево- и правостороннем движении.", ["grp.GroupGhost"]="Стоящий транспорт", ["opt.LightsInTraffic.L"]="Скорые включают мигалки, чтобы проехать через пробку", ["opt.LightsInTraffic.D"]="Скорая с пациентом на борту, но без сирены (игра включает её только для пациента в критическом состоянии), включает её, когда её задерживает поток, и выключает через несколько секунд после проезда. Пока сирена включена, машина получает всё, что положено спецмашине: приоритет, зелёные светофоры и перечисленные выше возможности.", },
                ["zh-HANS"] = new Dictionary<string, string> { ["opt.Enabled.L"]="启用紧急优先", ["opt.Enabled.D"]="让正在出勤的消防车、救护车和警车得以在交通拥堵中存活并继续行进。关闭 = 原版行为。", ["opt.DespawnGuard.L"]="防止受困出勤车辆消失", ["opt.DespawnGuard.D"]="原版会在出勤车辆被标记为受困于交通时将其删除，紧急任务则等待重新派遣。启用此保护后，车辆会转而寻找新路线。", ["opt.AutoReroute.L"]="绕开拥堵重新规划路线", ["opt.AutoReroute.D"]="原版只在派遣时规划一次路线。开启此项后，堵在拥堵中的出勤车辆会请求一条考虑当前交通状况的新路线。", ["opt.RerouteAfterSeconds.L"]="多少秒后重新规划路线（受阻秒数）", ["opt.RerouteAfterSeconds.D"]="出勤车辆必须连续受阻于交通多久后才会寻找绕行路线。", ["opt.GreenLightPriority.L"]="沿途路口亮绿灯", ["opt.GreenLightPriority.D"]="出勤车辆路线上的红绿灯会在其接近时变绿，并保持绿灯直到车辆通过。这是为了疏散它前方排队的车辆——紧急车辆本身原本就会闯红灯，等待的是它前面的普通车流。使用游戏自带的信号优先机制，因此正常的信号相位和人行横道依然会被遵守。", ["opt.GreenLightDistance.L"]="绿灯响应距离（米）", ["opt.GreenLightDistance.D"]="红绿灯会在出勤车辆前方多远处开始响应。信号灯安全切换需要几秒钟，因此距离越长，车辆抵达时已经是绿灯的可能性越大。距离越短，同时被打开的路口就越少。", ["grp.Group"]="出勤车辆", ["grp.GroupLights"]="红绿灯", ["grp.GroupGeneral"]="常规", ["opt.GhostThroughJams.L"]="穿过停滞车流", ["opt.GhostThroughJams.D"]="被本车道停滞车辆困住的应急车辆会穿过前方车辆继续前进，就像车队让出了道路。仅适用于停止的车辆：正前方的车，或在堵死的路口或环岛中停止的横向车辆。绝不适用于行驶中的横向车辆、行人或信号灯。游戏中车辆之间没有碰撞，因此短暂的重叠无害。", ["opt.GhostCrawlSpeed.L"]="穿过让行车流的速度（米/秒）", ["opt.GhostCrawlSpeed.D"]="应急车辆穿过停止或靠边让行的车辆时的移动速度。6 米/秒约合 22 公里/小时；3 米/秒是游戏本身允许车辆穿过障碍时使用的速度。", ["opt.TrafficPullsOver.L"]="慢速车流靠边让行", ["opt.TrafficPullsOver.D"]="在缓慢行驶的车流中，同一车道上应急车辆正前方的车会减速停下，就像靠边让行一样，应急车辆则穿过它——一辆接一辆，直到车队最前端。关闭 = 应急车辆只穿过已经停止的车辆。", ["opt.GhostUsesFreeLane.L"]="利用空闲车道超越车队", ["opt.GhostUsesFreeLane.D"]="排在车队后面的应急车辆会驶入空闲的相邻车道，在那里超越车队，并在路口前切回自己的车道——即使该车道用于其他转向。两侧均可，左行或右行交通均适用。", ["grp.GroupGhost"]="停滞车流", ["opt.LightsInTraffic.L"]="救护车开启警灯穿过车流", ["opt.LightsInTraffic.D"]="载有患者但未鸣笛的救护车（游戏仅在患者危重时鸣笛）在被车流阻挡时会开启警灯，并在通过几秒后关闭。警灯亮起期间，它享有应急车辆的一切待遇：优先权、绿灯以及上述选项。", },
                ["zh-HANT"] = new Dictionary<string, string> { ["opt.Enabled.L"]="啟用緊急優先", ["opt.Enabled.D"]="讓出勤中的消防車、救護車與警車在塞車中維持存在並持續移動。關閉＝原版行為。", ["opt.DespawnGuard.L"]="防止受困的出勤車輛消失", ["opt.DespawnGuard.D"]="原版在出勤車輛被標記為卡在車陣中後便將其刪除，緊急事件則等待重新派遣。啟用防護後，車輛會改為尋找新路線。", ["opt.AutoReroute.L"]="繞過壅塞重新規劃路線", ["opt.AutoReroute.D"]="原版只在派遣當下規劃一次路線。啟用後，卡在車陣中動彈不得的出勤車輛會請求一條考量當前交通狀況的新路線。", ["opt.RerouteAfterSeconds.L"]="重新規劃路線前等待（受阻秒數）", ["opt.RerouteAfterSeconds.D"]="出勤車輛在尋找繞道前，必須連續卡在車陣後方多久。", ["opt.GreenLightPriority.L"]="沿途路口亮綠燈", ["opt.GreenLightPriority.D"]="出勤車輛路線上的紅綠燈會在其接近時轉為綠燈，並維持綠燈直到車輛通過。這是為了疏散前方排隊的車流——緊急車輛本身原本就會闖紅燈，等待的是它前方的一般車流。使用遊戲內建的號誌優先機制，因此正常的號誌相位與行人穿越道仍會被遵守。", ["opt.GreenLightDistance.L"]="綠燈反應距離（公尺）", ["opt.GreenLightDistance.D"]="紅綠燈會在出勤車輛前方多遠處開始反應。號誌安全切換需要幾秒鐘，因此距離越長，車輛抵達時已經是綠燈的可能性越高。距離越短，同時開放的路口就越少。", ["grp.Group"]="出勤車輛", ["grp.GroupLights"]="紅綠燈", ["grp.GroupGeneral"]="一般", ["opt.GhostThroughJams.L"]="穿越停滯車流", ["opt.GhostThroughJams.D"]="被本車道停滯車輛困住的緊急車輛會穿過前方車輛繼續前進，就像車隊讓出了道路。僅適用於停止的車輛：正前方的車，或在堵死的路口或圓環中停止的橫向車輛。絕不適用於行駛中的橫向車輛、行人或號誌。遊戲中車輛之間沒有碰撞，因此短暫的重疊無害。", ["opt.GhostCrawlSpeed.L"]="穿越讓行車流的速度（公尺/秒）", ["opt.GhostCrawlSpeed.D"]="緊急車輛穿越停止或靠邊讓行的車輛時的移動速度。6 公尺/秒約為 22 公里/小時；3 公尺/秒是遊戲本身允許車輛穿過障礙時使用的速度。", ["opt.TrafficPullsOver.L"]="慢速車流靠邊讓行", ["opt.TrafficPullsOver.D"]="在緩慢行駛的車流中，同一車道上緊急車輛正前方的車會減速停下，就像靠邊讓行一樣，緊急車輛則穿過它——一輛接一輛，直到車隊最前端。關閉 = 緊急車輛只穿過已經停止的車輛。", ["opt.GhostUsesFreeLane.L"]="利用空閒車道超越車隊", ["opt.GhostUsesFreeLane.D"]="排在車隊後面的緊急車輛會駛入空閒的相鄰車道，在那裡超越車隊，並在路口前切回自己的車道——即使該車道用於其他轉向。兩側皆可，左行或右行交通均適用。", ["grp.GroupGhost"]="停滯車流", ["opt.LightsInTraffic.L"]="救護車開啟警示燈穿越車流", ["opt.LightsInTraffic.D"]="載有患者但未鳴笛的救護車（遊戲僅在患者危急時鳴笛）在被車流阻擋時會開啟警示燈，並在通過幾秒後關閉。警示燈亮起期間，它享有緊急車輛的一切待遇：優先權、綠燈以及上述選項。", },
        };
    }
}
